begin;

-- 1. Drop constraints blocking V2 code and sequence reuse
alter table public.central_catalogue drop constraint if exists central_catalogue_sequence_key;
alter table public.central_catalogue drop constraint if exists central_catalogue_sequence_check;
alter table public.central_catalogue drop constraint if exists central_catalogue_code_check;

-- 2. Safely deactivate superseded 407 V1 catalogue records without deletion
update public.central_catalogue
set is_active = false,
    sequence = 'OLD-' || sequence
where code not like 'CATV2-%' and sequence not like 'OLD-%';

-- 3. Add constraint for V2 code pattern
alter table public.central_catalogue add constraint central_catalogue_code_check check (code ~ '^CAT(V2)?-[0-9]{3}$');
create unique index if not exists central_catalogue_v2_sequence_key on public.central_catalogue(sequence) where code like 'CATV2-%';

-- 4. Extend schema for structured data and unit rules
alter table public.central_catalogue
  add column if not exists sku text,
  add column if not exists base_unit text not null default 'কেজি',
  add column if not exists is_restricted boolean not null default false,
  add column if not exists unit_conversions jsonb not null default '{}'::jsonb;

