  ('CATV2-282', '282', 'কাগজের ব্যাগ', 'বৈদ্যুতিক, স্টেশনারি ও প্যাকেজিং সামগ্রী', 'SKU-CATV2-282', 'পিস', false, '{"পিস":1,"জোড়া":2,"ডজন":12,"প্যাকেট":1,"বাক্স":12,"কার্টন":24}'::jsonb, true),
